def graph_for(kind,phase):
    key={('window','retrieve'):'retrieve',('compact','evidence'):'evidence',('gate','layers'):'layers',('gate','approval'):'approval',('cancel','settle'):'settle',('eval','layers'):'eval_layers'}.get((kind,phase),kind)
    return GRAPHS[key] if key in GRAPHS else None
